SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "胡惟庸被赐死", "description": "洪武13年（1380年）正月，胡惟庸被赐死。", "start_year": 1380, "end_year": 1380, "time_original": "洪武13年（1380年）正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "416a363c-0a2f-5e85-bd71-b523b2dccc1a"}, {"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年正月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "948d5fe2-ba88-587c-8744-a1aa466dc3fd"}, {"title": "明朝废除中书省的左右丞相、左右丞和参政等官职", "description": "洪武13年（1380年）正月，明朝废除中书省的左右丞相、左右丞和参政等官职。", "start_year": 1380, "end_year": 1380, "time_original": "洪武13年（1380年）正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "303fb770-feb4-5884-90b0-6860cdcb0eab"}, {"title": "明廷改定六部官员品秩", "description": "明廷重新规定六部官员的品秩。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8de42542-925c-59d6-a0a9-3d371d6994d9"}, {"title": "明廷改置五军都督府", "description": "明廷将大都督府改为中、左、右、前、后五军都督府。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "800a52d8-ab6c-5622-8d43-9f23824a39c4"}, {"title": "明廷下诏荐举多类人才", "description": "二月初一，朝廷下令荐举明达正直、孝悌勤农、贤良方正以及擅长文艺学问或术数的人。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年二月壬戌朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7aa51c9c-1f69-5671-a30c-82f6badda573"}, {"title": "明廷派发丹符清查金谷", "description": "朝廷发出丹符，查验各地钱粮数目。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a18ec8ea-0162-5018-b62f-0f9a9d08e139"}, {"title": "明廷准许六十岁以上官员退休", "description": "朝廷准许年满六十岁的文武官员退休，并发给诰敕。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年二月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "214bdce4-14f1-51ba-a3a0-5da9ec10b946"}, {"title": "明廷减免苏松嘉湖两成重赋", "description": "朝廷减去苏、松、嘉、湖所负较重赋税的十分之二。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年三月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bcf5e125-a16a-5583-858e-9fade8a15937"}, {"title": "燕王朱棣赴北平就藩", "description": "燕王朱棣前往封地北平。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年三月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "48180ffe-1a86-5ab1-9e26-ab05e08d3c40"}, {"title": "沐英在亦集乃俘获元将脱火赤", "description": "沐英在亦集乃袭击元将脱火赤，将其俘获，其部众归降。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年三月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "784b72c7-868f-5c37-b0c7-8a2346649e6b"}, {"title": "明廷命群臣各荐所知人才", "description": "朝廷命群臣各自荐举所了解的人才。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年四月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "eb5e5ef6-2427-5284-895a-da5897e0a318"}, {"title": "谨身殿遭雷击", "description": "本纪记载，五月甲午，雷击谨身殿。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年五月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "328aa143-2740-50a1-b355-7b64c24bbfcc"}, {"title": "明廷颁布大赦", "description": "明廷在这一日颁布大赦。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年五月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cc787274-631d-515c-af08-a3cddfb48b38"}, {"title": "明廷释放京师和临濠服役者", "description": "朝廷释放了在京师和临濠屯田服役的人。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年五月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "df6f6ae5-3d05-5615-8098-a2981707ec8f"}, {"title": "明廷宣布免征田租", "description": "朝廷下令免去天下田租。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年五月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d2ecae07-102b-5ceb-9239-fb252747a4ef"}, {"title": "明廷准许因过误被罢的吏员复职", "description": "原先因过误被罢免的吏员，获准回到原职。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5cdc03e9-4c4d-52d0-b463-9eb4b50f1b1a"}, {"title": "濮英在赤斤站俘获亦怜真等", "description": "都督濮英进兵赤斤站，俘获原元朝豳王亦怜真及其部众后返回。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年五月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "85e0e715-3ca5-54a1-b0e9-e732a09bdff7"}, {"title": "明廷撤销御史台", "description": "明廷在五月撤销御史台。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2cfc29bb-08c0-5e89-8129-3cbdd0706d10"}, {"title": "明廷规定老病从征士卒的替役和遣返", "description": "朝廷准许年老或患病的从征士卒由儿子替代。老而无子的人及寡妇，由主管官署资助回乡。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0265b1cc-851d-5e97-ba56-04ddcd091c4c"}, {"title": "奉天门雷击后朱元璋避居正殿之外", "description": "本纪记载，奉天门遭到雷击，朱元璋暂避正殿并反省自己的过失。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年六月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9bb1ad7f-eb78-538e-a451-50bf5ef92b06"}, {"title": "明廷停止王府工程劳役", "description": "明廷下令停止王府的工程劳役。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年六月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d532b2d0-b43c-54d9-afca-0b8ee69ccdbb"}, {"title": "明廷设置谏院官", "description": "朝廷设置负责谏诤的谏院官。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年六月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6b0547b-9679-5418-9ab5-b3ed6f1f9e00"}, {"title": "明廷规定学校师生每日有官给膳食", "description": "朝廷命各地学校每日向师生提供官给膳食。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dfed0762-6ccc-5aeb-874a-2b1fb718d943"}, {"title": "曹震杨璟薛显在北平屯田", "description": "景川侯曹震、营阳侯杨璟和永城侯薛显赴北平屯田。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年九月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "76747d0d-6bb9-5925-8acc-cae19d07ab7d"}, {"title": "朱元璋在天寿节受群臣朝贺", "description": "朱元璋首次在天寿节接受群臣朝贺，并在谨身殿赐宴。此后形成惯例。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年九月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d3df3af9-8c80-5052-b7ee-aac6c4baedb9"}, {"title": "明廷设置四辅官", "description": "明廷设四辅官并告祭太庙，又任命王本、杜佑、龚斅、杜斅、赵民望、吴源六名儒士担任春官和夏官。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年九月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "623428c9-1de3-5ca7-a3e0-fec1d69df3f2"}, {"title": "明廷命陕西卫军三分之二屯田", "description": "朝廷下诏，陕西卫军用三分之二的兵力从事屯田。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e2ada39b-ab0c-5db4-9070-9831bd18bc8e"}, {"title": "明廷将宋濂安置茂州", "description": "明廷将翰林学士承旨宋濂安置到茂州。本段还追记宋濂死在途中，未单列去世日期。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f481cb65-ca20-5943-83f0-1f7c228b307f"}, {"title": "徐达返回", "description": "本纪记载，徐达在十一月乙未返回。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年十一月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "362400c1-d082-5bbf-96c8-d900e3feaa6f"}, {"title": "元军进攻永平，王辂俘获完者不花", "description": "元将完者不花和乃儿不花进攻永平，明军指挥刘广战死。千户王辂率军击败来军，并俘获完者不花。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十三年十一月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "992ea842-1aac-5f0a-a0b8-2d0ce7b68f77"}, {"title": "明廷给八百六十余名荐举士人授官", "description": "各地府州县荐举的士人中有八百六十多人到达，朝廷分别授予官职。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十三年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3058948d-239a-53bb-bbf8-e146935dec39"}, {"title": "赵庸镇守广东并出兵阳春", "description": "南雄侯赵庸镇守广东，率军征讨阳春一带的反抗力量。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十三年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fae0f3ac-e1aa-5627-8075-b378a05b732b"}, {"title": "明廷因缺少表文退回日本来贡", "description": "这年琉球、日本、安南、占城、真腊和爪哇来贡。日本使者未带表文，明廷拒收贡品。 按原历纪年，事情发生在公元1380至1381年之间。", "start_year": null, "end_year": null, "time_original": "洪武十三年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "57bc2d6a-b9e4-5e2b-8a0f-95d87bbc39ef"}, {"title": "徐达等奉命出兵讨乃儿不花", "description": "明廷任命徐达为征虏大将军，汤和、傅友德分任左右副将军，率兵征讨乃儿不花。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年正月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "50d7c2e8-8eb9-5ecd-9b4d-d6cd7f71288a"}, {"title": "明廷命新授官员荐举人才", "description": "朝廷命新授官员各自荐举其了解的人才。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cb31dfc8-7112-5de8-bcfa-cb82ed0d5b0c"}, {"title": "明廷在南郊祭祀天地", "description": "明廷于正月乙未在南郊举行祭祀天地的大礼。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年正月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4ff49447-b4ec-5276-84ce-941cecd1de80"}, {"title": "明廷停止各地按年制造兵器的旧例", "description": "朝廷停止各地按年制造兵器的规定。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年正月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2007de3d-38c3-5738-b7a9-5ec307ea2ac6"}, {"title": "明廷命公侯子弟入国学", "description": "朝廷命公侯子弟进入国学学习。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年正月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bf4d59e9-8931-52fb-96ed-d73433dc3ce3"}, {"title": "明廷下诏征求隐居人才", "description": "朝廷下诏寻访隐居未仕的人才。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年正月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "044926d0-a8ba-5495-8aee-4e00b51361b3"}, {"title": "明廷核查各地官田", "description": "朝廷下令核查各地官田。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年二月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7b9e715f-deb8-5b94-93f6-9838bb54c884"}, {"title": "明廷颁布大赦", "description": "明廷在三月丙戌颁布大赦。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年三月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "11c92828-127e-548a-b077-560bea8fdd84"}, {"title": "明廷向北方学校颁发五经四书", "description": "明廷将《五经》和《四书》颁发给北方学校。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年三月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "be122e9e-c1e5-542e-a692-e49a7b9fae1b"}, {"title": "徐达出塞击败元军", "description": "徐达率领众将出塞，到达本纪所称北黄河，击败元军，俘获全宁四部后返回。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年四月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6bd52f64-07bd-5965-a7fc-def017fbd353"}, {"title": "周德兴平定五溪战事", "description": "五溪发生反抗，江夏侯周德兴率军平定。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4eef72b6-6b7c-56ff-b9b4-030f2eab27f4"}, {"title": "明廷征召通晓经书的老成士人", "description": "朝廷下诏寻找通晓经书、有阅历的士人，由主管官署以礼送往京师。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年八月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e615155e-7a66-509c-809c-4c6672a6b8c2"}, {"title": "黄河在原武祥符中牟决口", "description": "八月庚辰，黄河在原武、祥符和中牟决口。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年八月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9499099b-d394-537b-a797-a4ca2b4aff05"}, {"title": "徐达在八月返回", "description": "本纪记载，徐达在八月辛巳返回。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年八月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5f1bbf1c-0783-5aaf-9c36-116a3e4fc107"}, {"title": "傅友德蓝玉沐英奉命