ll, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ba587395-2d98-5890-b9be-de5661bed20c"}, {"title": "明廷分派御史复核囚案", "description": "朝廷分派御史到各处复查囚案。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年十月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e4e170fb-ce0a-51bd-9f89-79b1b4226e56"}, {"title": "唐胜宗率军平定浙东山地战事", "description": "延安侯唐胜宗率军征讨本纪所称的浙东山寇，平定当地战事。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年十月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a83f4493-c5ba-5572-b103-11f4b482f042"}, {"title": "陆仲亨镇守成都", "description": "吉安侯陆仲亨镇守成都。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年十一月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ca28bc6-be80-5ad2-8c4b-3915139dac44"}, {"title": "赵庸在广州击败海寇", "description": "本纪记载，赵庸在广州征讨海寇并大获全胜。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年十一月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "971208ed-a8ef-50b3-81a2-69437acc29d0"}, {"title": "明廷命翰林和春坊官审核各司章奏", "description": "朝廷命翰林和春坊官员审核各官署上报的奏章，对其中的问题提出异议。", "start_year": 1381, "end_year": 1381, "time_original": "洪武十四年十二月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7421e4b8-0b94-5e56-b7a1-f5e23753ef9a"}, {"title": "傅友德在白石江击败元军并攻下曲靖", "description": "傅友德率军在白石江击败元军，随后攻占曲靖。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十四年十二月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "19440f19-0dfd-5e84-a3eb-603084754277"}, {"title": "元梁王把匝剌瓦尔密在普宁自杀", "description": "元梁王把匝剌瓦尔密逃往普宁，随后自杀。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十四年十二月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8793d9d4-6bcd-5dc2-919c-f5424dc9e9a7"}, {"title": "明廷因安南进犯思明拒收其贡品", "description": "本纪列出暹罗、安南、爪哇、朵甘、乌斯藏来贡，并记载明廷因安南进犯思明而拒收其贡品。 按原历纪年，事情发生在公元1381至1382年之间。", "start_year": null, "end_year": null, "time_original": "洪武十四年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "be96dfcb-059d-5550-a603-d10364dc55f2"}]'::jsonb)
